<div class="hkp-head"><div><h1><?php echo hkp_e('Competencies'); ?></h1><p><?php echo hkp_e('Role → required competencies and levels → required learning, assessments and certification. A property can override the master matrix.'); ?></p></div>
<div class="hkp-actions"><a class="hkp-btn hkp-btn--ghost" href="<?php echo hkp_url('admin/crud/competencies'); ?>"><?php echo hkp_e('Competency library'); ?></a><a class="hkp-btn hkp-btn--ghost" href="<?php echo hkp_url('admin/crud/job_roles'); ?>"><?php echo hkp_e('Job roles'); ?></a><a class="hkp-btn" href="<?php echo hkp_url('admin/competencies/rubric'); ?>"><?php echo hkp_e('New rubric'); ?></a></div></div>
